        "text": "Erken gebelik olasılığı olan hastada ani şiddetlenen tek taraflı pelvik ağrı, presenkop, hipotansiyon, taşikardi, peritoneal irritasyon ve transvajinal ultrasonografide intrauterin kese olmamasıyla birlikte serbest sıvı bulunması kanayan ektopik gebelik paternini oluşturur. Bu klinik tabloda tanısal izlem veya medikal tedavi yerine maternal resüsitasyonla eş zamanlı acil cerrahi değerlendirme gerekir; amaç kanama kontrolünü geciktirmemektir."
